    if (F().raidPlan !== 'side') for (const [cx, cy] of this.doors.front.cells) World.map.set(cx, cy, 0);
    if (F().raidPlan !== 'front') for (const [cx, cy] of this.doors.side.cells) World.map.set(cx, cy, 0);
