    M.int({ id: 'chevyDone', x: W(22), y: W(29.6) - 6, r: 22, verb: 'Back to the Chevy', hint: 'Done for today', when: () => M.obj.filter(o => !o.optional).slice(0, 3).every(o => o.ok), act: () => { M.flags.back = true; } });
